package com.aac.ieojwo.media;import com.aac.ieojwo.common.api.ApiResponse;import com.aac.ieojwo.media.MediaStorageService.StoredImage;import org.springframework.core.io.Resource;import org.springframework.http.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.core.oidc.user.OidcUser;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;@RestController @RequestMapping("/api/v1/me/aac-users/{userId}/media")public class MediaController{private final MediaStorageService service;public MediaController(MediaStorageService s){service=s;}@PostMapping("/images")public ApiResponse<StoredImage> upload(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@RequestPart("file")MultipartFile file){return ApiResponse.ok(service.save(p,userId,file),"이미지가 업로드되었습니다.");}@GetMapping("/images/{name}")public ResponseEntity<Resource> image(@AuthenticationPrincipal OidcUser p,@PathVariable Long userId,@PathVariable String name){Resource r=service.load(p,userId,name);MediaType type=name.endsWith(".png")?MediaType.IMAGE_PNG:name.endsWith(".webp")?MediaType.parseMediaType("image/webp"):MediaType.IMAGE_JPEG;return ResponseEntity.ok().contentType(type).header(HttpHeaders.CACHE_CONTROL,"private, max-age=86400").body(r);}}
